import re

def _include_target(line: str) -> str | None:
    """Return the FILE of a ``-r FILE`` / ``--requirement FILE`` line, else None."""
    match = re.match(r"^\s*(?:-r|--requirement)(?:\s+|=)(.*)$", line)
    if match:
        target = match.group(1).strip()
        if len(target) >= 2 and target[0] in ("'", '"') and target[0] == target[-1]:
            target = target[1:-1]
        return target
    return None

