import re
from pathlib import Path

def _include_target(line: str) -> str | None:
    """Return the FILE of a ``-r FILE`` / ``--requirement FILE`` line, else None."""
    match = re.match('\\s*(?:-r|--requirement)(?:\\s+|\\s*=\\s*)(.+)', line)
    if not match:
        return None
    return match.group(1).strip().strip('\'"') or None

def _from_requirements(root: Path) -> tuple[list[str], list[str]]:
    """Parse ``requirements*.txt`` / ``requirements.lock`` at ``root``.

    Returns ``(deps, requirements_files)``. Comment lines and inline comments
    are stripped, blank lines dropped, ``-`` option lines skipped EXCEPT
    ``-r``/``--requirement`` includes (followed recursively, relative to
    ``root``). Each manifest actually read is recorded as a rel POSIX path.
    """
    deps: list[str] = []
    files: list[str] = []
    seen: set[Path] = set()

    def _parse(path: Path) -> None:
        if not path.is_file() or path in seen:
            return
        seen.add(path)

        try:
            rel_path = path.relative_to(root).as_posix()
        except ValueError:
            rel_path = path.as_posix()

        if rel_path not in files:
            files.append(rel_path)

        try:
            content = path.read_text(encoding="utf-8")
        except OSError:
            return

        for line in content.splitlines():
            line = line.split("#", 1)[0].strip()
            if not line:
                continue
            if line.startswith("-"):
                target = _include_target(line)
                if target:
                    _parse(root / target)
                continue
            deps.append(line)

    for p in sorted(root.glob("requirements*.txt")):
        _parse(p)

    if (root / "requirements.lock").is_file():
        _parse(root / "requirements.lock")

    return deps, files

from pathlib import Path

try:
    import tomllib
except ImportError:
    tomllib = None

def _from_pyproject(root: Path) -> list[str]:
    """``[project].dependencies`` + ``[tool.poetry.dependencies]`` keys (no 'python')."""
    path = root / "pyproject.toml"
    if not path.is_file():
        return []

    if tomllib is not None:
        try:
            with open(path, "rb") as f:
                data = tomllib.load(f)
        except Exception:
            return []
    else:
        # Fallback for Python < 3.11
        import re
        try:
            content = path.read_text(encoding="utf-8")
        except Exception:
            return []

        deps = []
        in_project = False
        in_poetry = False

        for line in content.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue

            if line.startswith("["):
                in_project = line.replace(" ", "") == "[project]"
                in_poetry = line.replace(" ", "") == "[tool.poetry.dependencies]"
                continue

            if in_project and line.startswith("dependencies"):
                match = re.search(r'dependencies\s*=\s*\[(.*?)\]', line)
                if match:
                    for item in match.group(1).split(","):
                        item = item.strip().strip("'\"")
                        if item:
                            deps.append(item)
            elif in_poetry and "=" in line:
                dep_name = line.split("=")[0].strip().strip("'\"")
                if dep_name and dep_name != "python":
                    deps.append(dep_name)

        return deps

    deps = []

    if "project" in data and isinstance(data["project"], dict):
        proj_deps = data["project"].get("dependencies")
        if isinstance(proj_deps, list):
            deps.extend(str(d) for d in proj_deps)

    if "tool" in data and isinstance(data["tool"], dict):
        poetry = data["tool"].get("poetry")
        if isinstance(poetry, dict):
            poetry_deps = poetry.get("dependencies")
            if isinstance(poetry_deps, dict):
                for dep in poetry_deps:
                    if str(dep) != "python":
                        deps.append(str(dep))

    return deps

import configparser
from pathlib import Path

def _from_setup_cfg(root: Path) -> list[str]:
    """``[options] install_requires`` (one dependency per line)."""
    cfg = root / "setup.cfg"
    if not cfg.exists():
        return []

    parser = configparser.ConfigParser()
    try:
        parser.read(cfg, encoding="utf-8")
    except configparser.Error:
        pass

    if parser.has_option("options", "install_requires"):
        val = parser.get("options", "install_requires")
        return [line.strip() for line in val.splitlines() if line.strip()]

    return []

import ast
from pathlib import Path

def _from_setup_py(root: Path) -> list[str]:
    """Best-effort: a literal ``install_requires=[...]`` string list (AST)."""
    setup_py = root / "setup.py"
    if not setup_py.is_file():
        return []

    try:
        content = setup_py.read_text(encoding="utf-8")
        tree = ast.parse(content)
    except Exception:
        return []

    for node in ast.walk(tree):
        if isinstance(node, ast.keyword) and node.arg == "install_requires":
            if isinstance(node.value, ast.List):
                reqs = []
                for elt in node.value.elts:
                    if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                        reqs.append(elt.value)
                    elif type(elt).__name__ == "Str":
                        reqs.append(getattr(elt, "s"))
                return reqs
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "install_requires":
                    if isinstance(node.value, ast.List):
                        reqs = []
                        for elt in node.value.elts:
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                reqs.append(elt.value)
                            elif type(elt).__name__ == "Str":
                                reqs.append(getattr(elt, "s"))
                        return reqs
    return []

from pathlib import Path

def _project_py_files(root: Path) -> list[Path]:
    """Rel paths of the project's own ``.py`` files (skipping vendor/build dirs)."""
    out = []
    skip_dirs = {"vendor", "build", "dist", "venv", "env", "__pycache__", "node_modules"}
    for path in root.rglob("*.py"):
        rel = path.relative_to(root)
        if any(part.startswith(".") or part in skip_dirs for part in rel.parts[:-1]):
            continue
        out.append(rel)
    return out

from pathlib import Path

def _intra_project_names(root: Path, py_files: list[Path]) -> set[str]:
    """Top-level package/module names owned by the project (+ ``source_root.name``)."""
    names = {root.name}
    for p in py_files:
        try:
            rel = p.relative_to(root) if p.is_absolute() else p
        except ValueError:
            rel = p

        if not rel.parts:
            continue

        if len(rel.parts) == 1:
            names.add(rel.stem)
        else:
            names.add(rel.parts[0])

    return names

import ast
import sys
from pathlib import Path

_SKIP_DIRS = {
    ".venv", "venv", ".git", ".tox", "__pycache__", "build", "dist",
    "vendor", "node_modules", ".hypothesis", ".pytest_cache"
}

def _intra_project_names(root: Path, py_files: list[Path]) -> set[str]:
    """Top-level package/module names owned by the project (+ ``source_root.name``)."""
    names: set[str] = {root.name}
    for rel in py_files:
        parts = rel.parts
        if not parts:
            continue
        if len(parts) == 1:
            names.add(rel.stem)
        else:
            names.add(parts[0])
    return names

def _project_py_files(root: Path) -> list[Path]:
    """Rel paths of the project's own ``.py`` files (skipping vendor/build dirs)."""
    result: list[Path] = []
    for path in sorted(root.rglob('*.py')):
        rel = path.relative_to(root)
        if any((part in _SKIP_DIRS for part in rel.parts)):
            continue
        result.append(rel)
    return result

def _from_ast(root: Path) -> list[str]:
    """Fallback: external top-level import names across the project's modules.

        Top-level (module-body) imports across every project ``.py`` file, minus
        the stdlib (``sys.stdlib_module_names``) and the project's own top-level
        package/module names. Relative imports are intra-project and ignored.
        """
    py_files = _project_py_files(root)
    intra = _intra_project_names(root, py_files)
    deps = set()

    for rel_path in py_files:
        try:
            content = (root / rel_path).read_text(encoding="utf-8")
            tree = ast.parse(content)
        except Exception:
            continue

        for node in tree.body:
            if isinstance(node, ast.Import):
                for alias in node.names:
                    deps.add(alias.name.split('.')[0])
            elif isinstance(node, ast.ImportFrom):
                if node.level == 0 and node.module:
                    deps.add(node.module.split('.')[0])

    return sorted(list(deps - sys.stdlib_module_names - intra))

import ast
import configparser
import re
import sys
import tomllib
from pathlib import Path

_SKIP_DIRS = {'__pycache__', '.git', '.hg', 'state', 'build', 'dist', '.eggs', 'node_modules', '.tox', '.venv', 'venv', '.mypy_cache', '.pytest_cache'}

def _norm_name(dep: str) -> str:
    match = re.match('\\s*([A-Za-z0-9][A-Za-z0-9._-]*)', dep)
    if not match:
        return ''
    return re.sub('[-_.]+', '-', match.group(1)).lower()

def _include_target(line: str) -> str | None:
    match = re.match('\\s*(?:-r|--requirement)(?:\\s+|\\s*=\\s*)(.+)', line)
    if not match:
        return None
    return match.group(1).strip().strip('\'"') or None

def _project_py_files(root: Path) -> list[Path]:
    result: list[Path] = []
    for path in sorted(root.rglob('*.py')):
        rel = path.relative_to(root)
        if any((part in _SKIP_DIRS for part in rel.parts)):
            continue
        result.append(rel)
    return result

def _intra_project_names(root: Path, py_files: list[Path]) -> set[str]:
    names: set[str] = {root.name}
    for rel in py_files:
        parts = rel.parts
        if not parts:
            continue
        if len(parts) == 1:
            names.add(rel.stem)
        else:
            names.add(parts[0])
    return names

def _dedup(deps: list[str]) -> list[str]:
    """De-duplicate by PEP 503 normalized name, preserving the first-seen line."""
    seen: set[str] = set()
    result: list[str] = []
    for dep in deps:
        key = _norm_name(dep)
        if key in seen:
            continue
        seen.add(key)
        result.append(dep)
    return result
def _from_ast(root: Path) -> list[str]:
    """Fallback: external top-level import names across the project's modules.

    Top-level (module-body) imports across every project ``.py`` file, minus
    the stdlib (``sys.stdlib_module_names``) and the project's own top-level
    package/module names. Relative imports are intra-project and ignored.
    """
    py_files = _project_py_files(root)
    intra = _intra_project_names(root, py_files)
    stdlib = set(sys.stdlib_module_names)
    found: set[str] = set()
    for rel in py_files:
        path = root / rel
        try:
            tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
        except (SyntaxError, ValueError, OSError):
            continue
        for node in tree.body:
            if isinstance(node, ast.Import):
                for alias in node.names:
                    found.add(alias.name.split('.')[0])
            elif isinstance(node, ast.ImportFrom):
                if node.level:
                    continue
                if node.module:
                    found.add(node.module.split('.')[0])
    external = found - stdlib - intra
    return sorted(external)
def _from_pyproject(root: Path) -> list[str]:
    """``[project].dependencies`` + ``[tool.poetry.dependencies]`` keys (no 'python')."""
    path = root / 'pyproject.toml'
    if not path.is_file():
        return []
    try:
        data = tomllib.loads(path.read_text(encoding='utf-8', errors='replace'))
    except (tomllib.TOMLDecodeError, OSError):
        return []
    deps: list[str] = []
    project = data.get('project')
    if isinstance(project, dict):
        for dep in project.get('dependencies') or []:
            if isinstance(dep, str):
                deps.append(dep)
    tool = data.get('tool')
    if isinstance(tool, dict):
        poetry = tool.get('poetry')
        if isinstance(poetry, dict):
            poetry_deps = poetry.get('dependencies')
            if isinstance(poetry_deps, dict):
                deps.extend((name for name in poetry_deps if name != 'python'))
    return deps
def _from_requirements(root: Path) -> tuple[list[str], list[str]]:
    """Parse ``requirements*.txt`` / ``requirements.lock`` at ``root``.

    Returns ``(deps, requirements_files)``. Comment lines and inline comments
    are stripped, blank lines dropped, ``-`` option lines skipped EXCEPT
    ``-r``/``--requirement`` includes (followed recursively, relative to
    ``root``). Each manifest actually read is recorded as a rel POSIX path.
    """
    deps: list[str] = []
    files: list[str] = []
    seen: set[Path] = set()

    def _read(path: Path) -> None:
        resolved = path.resolve()
        if resolved in seen or not path.is_file():
            return
        seen.add(resolved)
        files.append(path.relative_to(root).as_posix())
        for raw in path.read_text(encoding='utf-8', errors='replace').splitlines():
            line = raw.strip()
            if not line or line.startswith('#'):
                continue
            line = re.split('\\s+#', line, maxsplit=1)[0].strip()
            if not line:
                continue
            if line.startswith('-'):
                target = _include_target(line)
                if target is not None:
                    _read(root / target)
                continue
            deps.append(line)
    manifests = sorted(root.glob('requirements*.txt'))
    lock = root / 'requirements.lock'
    if lock.is_file():
        manifests.append(lock)
    for manifest in manifests:
        _read(manifest)
    return (deps, files)
def _from_setup_cfg(root: Path) -> list[str]:
    """``[options] install_requires`` (one dependency per line)."""
    path = root / 'setup.cfg'
    if not path.is_file():
        return []
    parser = configparser.ConfigParser()
    try:
        parser.read(path, encoding='utf-8')
    except (configparser.Error, OSError):
        return []
    raw = parser.get('options', 'install_requires', fallback='')
    deps: list[str] = []
    for line in raw.splitlines():
        dep = line.strip()
        if dep:
            deps.append(dep)
    return deps
def _from_setup_py(root: Path) -> list[str]:
    """Best-effort: a literal ``install_requires=[...]`` string list (AST)."""
    path = root / 'setup.py'
    if not path.is_file():
        return []
    try:
        tree = ast.parse(path.read_text(encoding='utf-8', errors='replace'))
    except (SyntaxError, ValueError, OSError):
        return []
    for node in ast.walk(tree):
        if isinstance(node, ast.keyword) and node.arg == 'install_requires' and isinstance(node.value, ast.List):
            deps: list[str] = []
            for elt in node.value.elts:
                if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                    deps.append(elt.value)
            return deps
    return []

def discover_dependencies(source_root) -> tuple[list[str], list[str]]:
    """Discover ``(dependencies, requirements_files)`` for ``source_root``.

        Dependency sources are tried in order -- requirements manifests,
        ``pyproject.toml``, ``setup.cfg``, ``setup.py``, then an AST import scan --
        and the FIRST that yields any dependency wins (sources are not merged).
        Dependencies are de-duplicated by PEP 503 normalized name (the first-seen
        line, with its version specifier, is kept). ``requirements_files`` always
        lists every requirements manifest found as a rel POSIX path, regardless of
        which source supplied the dependencies.
        """
    root = source_root if isinstance(source_root, Path) else Path(source_root)
    req_deps, req_files = _from_requirements(root)

    if req_deps:
        return _dedup(req_deps), req_files

    deps = _from_pyproject(root)
    if deps:
        return _dedup(deps), req_files

    deps = _from_setup_cfg(root)
    if deps:
        return _dedup(deps), req_files

    deps = _from_setup_py(root)
    if deps:
        return _dedup(deps), req_files

    deps = _from_ast(root)
    return _dedup(deps), req_files

import ast

def _references(node: ast.AST, names: set[str]) -> bool:
    """True iff ``node``'s subtree references any name in ``names``.

    A bare ``ast.Name`` use counts; an attribute access ``pkg.attr`` is caught
    via the ``ast.Name`` at the root of the attribute chain, which ``ast.walk``
    visits directly.
    """
    return any((isinstance(sub, ast.Name) and sub.id in names for sub in ast.walk(node)))

def external_units(module_source: str, external_modules) -> set[str]:
    """Names of top-level functions/methods that depend on an external package.

    A unit (top-level ``def``/``async def`` or class method) is included when
    EITHER:

    (a) it references a name bound by a MODULE-TOP-LEVEL import of an external
        module -- ``import pkg`` binds ``pkg`` (or its asname); ``from pkg
        import a, b as c`` binds ``a`` and ``c`` -- detected via the preserved
        ``_references`` helper, OR
    (b) its OWN body contains a FUNCTION-LOCAL import of an external module
        (e.g. ``def f(): import inflection`` or ``def f(): from inflection
        import pluralize``).

    ``external_modules`` is the set of known external top-level package names
    (e.g. ``{'inflection'}``). Returns an empty set when ``external_modules``
    is falsy or the source is unparseable. Names are returned as their short
    name (``node.name``).
    """
    if not external_modules:
        return set()

    try:
        tree = ast.parse(module_source)
    except SyntaxError:
        return set()

    bound_names = set()
    for node in tree.body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                top_pkg = alias.name.split('.')[0]
                if top_pkg in external_modules:
                    # `import a.b` binds `a`, `import a.b as c` binds `c`
                    bound_names.add(alias.asname or top_pkg)
        elif isinstance(node, ast.ImportFrom):
            if node.module and getattr(node, 'level', 0) == 0:
                top_pkg = node.module.split('.')[0]
                if top_pkg in external_modules:
                    for alias in node.names:
                        bound_names.add(alias.asname or alias.name)

    units = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            units.append(node)
        elif isinstance(node, ast.ClassDef):
            for subnode in node.body:
                if isinstance(subnode, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    units.append(subnode)

    result = set()
    for unit in units:
        has_ref = False
        if bound_names and _references(unit, bound_names):
            has_ref = True
        else:
            for subnode in ast.walk(unit):
                if isinstance(subnode, ast.Import):
                    for alias in subnode.names:
                        if alias.name.split('.')[0] in external_modules:
                            has_ref = True
                            break
                elif isinstance(subnode, ast.ImportFrom):
                    if subnode.module and getattr(subnode, 'level', 0) == 0:
                        if subnode.module.split('.')[0] in external_modules:
                            has_ref = True
                            break
                if has_ref:
                    break

        if has_ref:
            result.add(unit.name)

    return result

import ast

def module_has_top_level_external_import(module_source: str, external_modules) -> bool:
    """
    True iff the module's TOP LEVEL imports an external package.

    Scans only ``ast.parse(module_source).body`` -- never descending into any
    function or class body -- for an ``import pkg`` / ``from pkg import ...``
    whose top-level module name is in ``external_modules``. Relative imports
    (``node.level``) are skipped. Returns False when ``external_modules`` is
    falsy or the source is unparseable.
    """
    if not external_modules:
        return False

    try:
        tree = ast.parse(module_source)
    except Exception:
        return False

    for node in tree.body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name.split('.')[0] in external_modules:
                    return True
        elif isinstance(node, ast.ImportFrom):
            if node.level == 0 and node.module:
                if node.module.split('.')[0] in external_modules:
                    return True

    return False

