import ast

def _module_global_names(tree: ast.Module) -> set[str]:
    """Names bound at MODULE top level (the module's mutable global state)."""
    bound_names = set()

    class Visitor(ast.NodeVisitor):
        def visit_Name(self, node):
            if isinstance(node.ctx, ast.Store):
                bound_names.add(node.id)

        def visit_FunctionDef(self, node):
            bound_names.add(node.name)
            for deco in node.decorator_list:
                self.visit(deco)
            if getattr(node, 'returns', None):
                self.visit(node.returns)
            self.visit(node.args)

        def visit_AsyncFunctionDef(self, node):
            self.visit_FunctionDef(node)

        def visit_ClassDef(self, node):
            bound_names.add(node.name)
            for deco in node.decorator_list:
                self.visit(deco)
            for base in node.bases:
                self.visit(base)
            for kw in node.keywords:
                self.visit(kw)

        def visit_Import(self, node):
            for alias in node.names:
                if alias.asname:
                    bound_names.add(alias.asname)
                else:
                    bound_names.add(alias.name.split('.')[0])

        def visit_ImportFrom(self, node):
            for alias in node.names:
                if alias.name != '*':
                    bound_names.add(alias.asname or alias.name)

        def visit_ExceptHandler(self, node):
            if getattr(node, 'name', None):
                bound_names.add(node.name)
            self.generic_visit(node)

        def visit_MatchAs(self, node):
            if getattr(node, 'name', None) is not None:
                bound_names.add(node.name)
            self.generic_visit(node)

        def visit_MatchMapping(self, node):
            if getattr(node, 'rest', None) is not None:
                bound_names.add(node.rest)
            self.generic_visit(node)

        def visit_MatchStar(self, node):
            if getattr(node, 'name', None) is not None:
                bound_names.add(node.name)
            self.generic_visit(node)

        def visit_Lambda(self, node):
            pass

        def visit_ListComp(self, node):
            pass

        def visit_SetComp(self, node):
            pass

        def visit_DictComp(self, node):
            pass

        def visit_GeneratorExp(self, node):
            pass

    Visitor().visit(tree)
    return bound_names

