def order_modules(source_root: Path, modules: list[str]) -> list[str]:
    graph = module_import_graph(source_root, modules)
    visited = set()
    temp_visited = set()
    result = []

    def dfs(mod: str):
        if mod in visited:
            return
        if mod in temp_visited:
            return
        temp_visited.add(mod)
        for dep in [d for d in modules if d in graph.get(mod, set())]:
            dfs(dep)
        temp_visited.remove(mod)
        visited.add(mod)
        result.append(mod)

    for mod in modules:
        dfs(mod)
    return result

