import sys
import json

def main() -> None:
    try:
        raw_input = sys.stdin.read()
        if not raw_input:
            print(json.dumps({"decision": "allow"}))
            return

        data = json.loads(raw_input)

        if not isinstance(data, dict):
            print(json.dumps({"decision": "deny", "reason": "Blocked tool"}))
            return

        if "tool_name" not in data:
            print(json.dumps({"decision": "deny", "reason": "Blocked tool"}))
            return

        tool_name = data.get("tool_name")

        if tool_name == "mcp__janusmask__execute":
            print(json.dumps({"decision": "allow"}))
            return

        print(json.dumps({"decision": "deny", "reason": f"Blocked tool: {tool_name}"}))

    except Exception as e:
        print(json.dumps({"decision": "deny", "reason": f"Malformed hook input: {e}"}))

if __name__ == "__main__":
    main()

