import ast
import inspect

def fuzz(module_name: str, module_src: str, *, timeout: float=5.0) -> str | None:
    """Narrow-fuzz the candidate's validator-like functions.

    See module docstring for design contract; brief §4.1, §11.2, §13
    are the binding spec.
    """
    try:
        tree = ast.parse(module_src)
    except SyntaxError:
        return None

    run_always = globals().get('_RUN_ALWAYS', False)

    if not run_always:
        has_tests = False
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if node.name.startswith('test_'):
                    has_tests = True
                    break
        if has_tests:
            return None

    validator_names = _discover_validators(module_src)
    if not validator_names:
        return None

    mod_dict = _exec_module(module_name, module_src)
    if not mod_dict:
        return None

    for name in validator_names:
        fn = mod_dict.get(name)
        if not callable(fn):
            continue

        if inspect.iscoroutinefunction(fn):
            continue

        meta = _meta_for(fn)
        if meta.get('skip'):
            continue

        sig = getattr(fn, '__annotations__', {})
        strategies = _build_strategies(sig)
        if strategies is None:
            continue

        err = _fuzz_one(fn, name, strategies, timeout)
        if err is not None:
            return err

    return None

